        ["cs2.shader.sub"] = ["CS2 compiled shaders. Steam rebuilds them when the game opens. The folder is found in all your Steam libraries.", "Shaders compilados de CS2. Steam los regenera al abrir el juego. La carpeta se busca sola en todas tus bibliotecas de Steam.", "Скомпилированные шейдеры CS2. Steam пересоздаёт их при запуске игры. Папка ищется во всех библиотеках Steam.", "Kompilierte CS2-Shader. Steam erzeugt sie beim Spielstart neu. Der Ordner wird in allen Steam-Bibliotheken gesucht.", "Shaders compilés de CS2. Steam les recrée au lancement du jeu. Le dossier est recherché dans toutes vos bibliothèques Steam.", "CS2 已编译的着色器，游戏启动时 Steam 会重新生成。会自动在所有 Steam 库中查找该文件夹。"],
        ["cs2.shader.btn"] = ["Delete shader cache", "Borrar shadercache", "Удалить кэш шейдеров", "Shadercache löschen", "Supprimer le cache", "删除着色器缓存"],
        ["cs2.browse"] = ["Choose folder (steamapps\\shadercache\\730)", "Elegir carpeta (steamapps\\shadercache\\730)", "Выбрать папку (steamapps\\shadercache\\730)", "Ordner wählen (steamapps\\shadercache\\730)", "Choisir le dossier (steamapps\\shadercache\\730)", "选择文件夹 (steamapps\\shadercache\\730)"],
        ["cs2.detect"] = ["Detect", "Detectar", "Найти", "Erkennen", "Détecter", "检测"],
        ["cs2.mouse.sub"] = ["Imports raton.reg (pointer acceleration off and mouse tweaks). It ships inside the program.", "Importa raton.reg (aceleración del puntero desactivada y ajustes del ratón). Viene dentro del programa.", "Импортирует raton.reg (без ускорения указателя и с настройками мыши). Входит в программу.", "Importiert raton.reg (Zeigerbeschleunigung aus, Mausanpassungen). Ist im Programm enthalten.", "Importe raton.reg (accélération du pointeur désactivée et réglages de la souris). Inclus dans le programme.", "导入 raton.reg（关闭指针加速并调整鼠标设置）。已内置于程序中。"],
        ["cs2.mouse.btn"] = ["Apply raton.reg", "Aplicar raton.reg", "Применить raton.reg", "raton.reg anwenden", "Appliquer raton.reg", "应用 raton.reg"],
        ["cs2.nv.sub"] = ["Imports CS2.nip with NVIDIA Profile Inspector silently. Both ship inside the program.", "Importa CS2.nip con NVIDIA Profile Inspector en modo silencioso. Los dos vienen dentro del programa.", "Импортирует CS2.nip через NVIDIA Profile Inspector в тихом режиме. Оба файла входят в программу.", "Importiert CS2.nip still mit NVIDIA Profile Inspector. Beides ist im Programm enthalten.", "Importe CS2.nip avec NVIDIA Profile Inspector en mode silencieux. Les deux sont inclus dans le programme.", "使用 NVIDIA Profile Inspector 静默导入 CS2.nip。两者均已内置。"],
        ["cs2.nv.none"] = ["No NVIDIA GPU was detected on this PC: this module only works with NVIDIA cards.", "No se ha detectado una GPU NVIDIA en este equipo: este módulo solo funciona con tarjetas NVIDIA.", "Видеокарта NVIDIA не найдена: модуль работает только с картами NVIDIA.", "Keine NVIDIA-GPU gefunden: Dieses Modul funktioniert nur mit NVIDIA-Karten.", "Aucun GPU NVIDIA détecté : ce module ne fonctionne qu'avec les cartes NVIDIA.", "未检测到 NVIDIA 显卡：此模块仅适用于 NVIDIA 显卡。"],
        ["cs2.nv.open"] = ["Open Inspector", "Abrir Inspector", "Открыть Inspector", "Inspector öffnen", "Ouvrir Inspector", "打开 Inspector"],
        ["cs2.nv.btn"] = ["Import profile", "Importar perfil", "Импорт профиля", "Profil importieren", "Importer le profil", "导入配置文件"],
        ["sc.title"] = ["Desktop shortcuts", "Accesos directos", "Ярлыки на рабочем столе", "Desktop-Verknüpfungen", "Raccourcis sur le bureau", "桌面快捷方式"],
        ["sc.sub"] = ["Runs a mode straight away and closes when it finishes.", "Ejecuta un modo directamente y se cierra al terminar.", "Сразу запускает режим и закрывается по завершении.", "Startet einen Modus direkt und schließt sich danach.", "Lance un mode directement et se ferme à la fin.", "直接运行一个模式，完成后自动关闭。"],
        ["sc.todo"] = ["Everything shortcut", "Acceso Todo", "Ярлык «Всё»", "Verknüpfung „Alles“", "Raccourci Tout", "“全部”快捷方式"],
        ["sc.nobackup"] = ["No-backup shortcut", "Acceso sin backup", "Ярлык без копии", "Verknüpfung ohne Sicherung", "Raccourci sans sauvegarde", "“不备份”快捷方式"],
