        ["bk.exclude.hint"] = ["760 = screenshots · gamerecordings = clips · the rest are caches Steam rebuilds.", "760 = capturas · gamerecordings = clips · el resto son cachés que Steam regenera.", "760 = скриншоты · gamerecordings = клипы · остальное — кэши, которые Steam пересоздаёт.", "760 = Screenshots · gamerecordings = Clips · der Rest sind Caches, die Steam neu erstellt.", "760 = captures · gamerecordings = clips · le reste sont des caches que Steam recrée.", "760 = 截图 · gamerecordings = 录像 · 其余为 Steam 会重建的缓存。"],
